{
  "word": "无量",
  "definition_simple": "Countless or boundless; immeasurable.",
  "definition_standard": "没有 限量，多得 无法 计算；无限 的。",
  "pos": "adj",
  "semantic_class": "Quantity/Degree",
  "examples": [
    {
      "sentence": "功德无量",
      "translation": "immeasurable boundless virtue/merit",
      "tier": "T1"
    },
    {
      "sentence": "前途无量",
      "translation": "boundless future / a brilliant future",
      "tier": "T2"
    },
    {
      "sentence": "前程无量",
      "translation": "boundless prospects",
      "tier": "T2"
    },
    {
      "sentence": "无量寿佛",
      "translation": "Infinite Life Buddha",
      "tier": "T3"
    },
    {
      "sentence": "这孩子聪明伶俐，将来前途无量。",
      "translation": "This child is smart and clever, and has a boundless future ahead.",
      "tier": "T4"
    },
    {
      "sentence": "他做了一件造福百姓的好事，可谓功德无量。",
      "translation": "He did a good deed that benefited the people, which can be described as bringing immeasurable merit.",
      "tier": "T4"
    },
    {
      "sentence": "宇宙浩瀚无垠，其空间与能量皆为无量之数。",
      "translation": "The universe is vast and boundless, and its space and energy are both immeasurable quantities.",
      "tier": "T5"
    },
    {
      "sentence": "在漫长的历史长河中，人类创造了无量数宝贵的精神财富。",
      "translation": "In the long river of history, mankind has created immeasurable amounts of precious spiritual wealth.",
      "tier": "T5"
    },
    {
      "sentence": "佛教经典中常以“无量”来形容佛法的深广与智慧的无边。",
      "translation": "Buddhist scriptures often use \"immeasurable\" to describe the profundity of the Dharma and the boundlessness of wisdom.",
      "tier": "T6"
    },
    {
      "sentence": "面对无量诸法，修行者当保持觉照，不生执着。",
      "translation": "Facing the immeasurable phenomena, practitioners should maintain awareness and not generate attachment.",
      "tier": "T6"
    }
  ],
  "morphological_forms": [
    "无量数",
    "无量劫"
  ],
  "primary_collocate": "前途",
  "word_family_forms": [
    "无限",
    "量大"
  ],
  "syn_ant_candidates": {
    "synonyms": [
      "无限",
      "浩瀚",
      "无穷",
      "莫测"
    ],
    "antonyms": [
      "有限",
      "有限度",
      "寥寥"
    ]
  }
}
